#!/bin/bash
# Fills in DATASET_PASSWORD from the Kubernetes secret when it is not already set.
#
# The dataset role's password is generated by the chart, so dev.db/.env cannot know
# it. Source this AFTER sourcing .env - `set -a; source .env` would otherwise put the
# empty value from .env back over an inherited one.
#
# Override by setting DATASET_PASSWORD in .env or the environment.

if [ -z "${DATASET_PASSWORD:-}" ]; then
  DATASET_PASSWORD=$(kubectl get secret "${DATASET_SECRET_NAME:-db-datasets-uc1}" \
    -n "${NAMESPACE:-fn}" -o jsonpath='{.data.password}' 2>/dev/null | base64 -d)
  export DATASET_PASSWORD
fi

if [ -z "${DATASET_PASSWORD:-}" ]; then
  echo "DATASET_PASSWORD is not set and the ${DATASET_SECRET_NAME:-db-datasets-uc1} secret" >&2
  echo "in namespace ${NAMESPACE:-fn} could not be read. Try 'make show-db-passwords'," >&2
  echo "or set DATASET_PASSWORD in dev.db/.env." >&2
  exit 1
fi
